#include <bits/stdc++.h>
using namespace std;

using i128 = __int128_t;

i128 gcd128(i128 a, i128 b) {
    while (b != 0) {
        i128 r = a % b;
        a = b;
        b = r;
    }
    return a;
}

void print128(i128 x) {
    if (x == 0) {
        cout << '0';
        return;
    }
    if (x < 0) {
        cout << '-';
        x = -x;
    }
    string s;
    while (x > 0) {
        s.push_back(char('0' + x % 10));
        x /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b, c, d;
    cin >> a >> b >> c >> d;

    i128 best = 0;
    int bestX = 1, bestY = 1;
    bool found = false;

    for (int i = 1; i <= 1000; ++i) {
        for (int j = 1; j <= 1000; ++j) {
            i128 x = (i128)a * b * j * j;
            i128 y = (i128)c * d * i * i;
            i128 diff = y - x;

            if (diff >= 0 && (!found || diff < best)) {
                found = true;
                best = diff;
                bestX = j;
                bestY = i;
            }
        }
    }

    i128 x = (i128)a * b * bestX * bestX;
    i128 y = (i128)c * d * bestY * bestY;
    i128 numerator = y - x;
    i128 divisor = gcd128(numerator, y);

    print128(numerator / divisor);
    cout << '/';
    print128(y / divisor);
    cout << '\n';

    return 0;
}

